// /asset-stamp:precache

const CACHE_NAME = `stemprofile-${CACHE_VERSION}`;
const CACHE_PREFIX = 'stemprofile-';

/** Absolute URL -> expected SHA-256 (hex) for every precached file. */
const EXPECTED = new Map(Object.entries(INTEGRITY).map(([url, hash]) => [new URL(url, self.location).href, hash]));

/** The URL without query or fragment: pages are cached once, whatever the share-link search. */
function bareUrl(url) {
  const u = new URL(url);
  u.search = '';
  u.hash = '';
  return u.href;
}

async function sha256Hex(response) {
  const digest = await crypto.subtle.digest('SHA-256', await response.clone().arrayBuffer());
  return Array.from(new Uint8Array(digest), b => b.toString(16).padStart(2, '0')).join('');
}

/** True when the response body is exactly the deployed file for `url`. Unknown URLs never verify. */
async function matchesIntegrity(url, response) {
  const expected = EXPECTED.get(url);
  return Boolean(expected && response && response.ok && await sha256Hex(response) === expected);
}

/**
 * The cached copy of `url`, only if it is intact. A tampered or stale entry is
 * deleted, so it is never served and the next fetch replaces it.
 */
async function verifiedMatch(cache, url) {
  const cached = await cache.match(url);
  if (!cached) return null;
  if (await matchesIntegrity(url, cached)) return cached;
  await cache.delete(url);
  return null;
}

/** Stores a network response, but only when it is the exact file this worker expects. */
async function putIfIntact(cache, url, response) {
  if (await matchesIntegrity(url, response)) await cache.put(url, response.clone());
}

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    await Promise.all(PRECACHE.map(async path => {
      const url = new URL(path, self.location).href;
      // Skip the HTTP cache: GitHub Pages may still hold the previous deploy for 10 minutes
      const response = await fetch(url, { cache: 'no-cache' });
      // A mismatch fails the install, so the old (intact) worker stays until the next visit
      if (!await matchesIntegrity(url, response)) throw new Error(`Precache integrity mismatch: ${path}`);
      await cache.put(url, response);
    }));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys
        .filter(key => key.startsWith(CACHE_PREFIX) && key !== CACHE_NAME)
        .map(key => caches.delete(key))))
      .then(() => self.clients.claim())
  );
});

/** Network first, falling back to the verified cached page (the app shell for the root). */
async function networkFirst(request) {
  const cache = await caches.open(CACHE_NAME);
  const url = bareUrl(request.url);
  try {
    const response = await fetch(request);
    await putIfIntact(cache, url, response);
    return response;
  } catch (err) {
    const cached = await verifiedMatch(cache, url);
    if (cached) return cached;
    if (request.mode === 'navigate') {
      const shell = await verifiedMatch(cache, new URL('./', self.location).href);
      if (shell) return shell;
    }
    throw err;
  }
}

/** Cache first; versioned URLs are immutable, so an intact hit is always current. */
async function cacheFirst(request) {
  const cache = await caches.open(CACHE_NAME);
  const cached = await verifiedMatch(cache, request.url);
  if (cached) return cached;
  const response = await fetch(request);
  await putIfIntact(cache, request.url, response);
  return response;
}

self.addEventListener('fetch', event => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  event.respondWith(url.searchParams.has('v') ? cacheFirst(request) : networkFirst(request));
});
